class Solution {
  private static final long INF = Long.MAX_VALUE / 4;
  private int sx, sy;

  private long solve(long x, long y) {
    long steps = 0;
    while (true) {
      if (x == sx && y == sy) return steps;
      if (x < sx || y < sy) return INF;
      if (x == y) {
        return 1 + Math.min(solve(0, y), solve(x, 0)) + steps;
      }
      if (x > y) {
        if (x >= 2 * y) {
          if (x % 2 != 0) return INF;
          x /= 2;
        } else {
          x -= y;
        }
      } else {
        if (y >= 2 * x) {
          if (y % 2 != 0) return INF;
          y /= 2;
        } else {
          y -= x;
        }
      }
      steps++;
    }
  }

  public int minMoves(int sx, int sy, int tx, int ty) {
    this.sx = sx;
    this.sy = sy;
    long res = solve(tx, ty);
    return res >= INF ? -1 : (int) res;
  }
}
